set -e
cd "$(dirname "$0")"
mkdir -p dl store/media
cat > get-range.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh get-range.sh URL FIRST LAST FILE [curl options...]
# Fetches bytes FIRST to LAST of an object into FILE. When a try ends short, the next one asks
# only for the bytes after those FILE holds; at most 5 tries. Prints each try's Range, status,
# bytes received and curl's exit code, then the bytes fetched in all. An error status (4xx, 5xx)
# is not a lost connection: the script stops there, exit 1.
url=$1 first=$2 last=$3 file=$4
shift 4
: > "$file"
tries=0 fetched=0
while :; do
  have=$(wc -c < "$file" | tr -d ' ')
  from=$((first + have))
  if [ "$from" -gt "$last" ]; then break; fi
  if [ "$tries" -ge 5 ]; then echo "gave up after $tries tries" >&2; exit 1; fi
  tries=$((tries + 1))
  got=$(curl -s -f "$@" -r "$from-$last" -o "$file.try" -w "%{http_code} %{size_download}" "$url")
  code=$?
  echo "bytes=$from-$last: $got, exit $code"
  case "$got" in 4*|5*) exit 1 ;; esac
  fetched=$((fetched + ${got#* }))
  if [ -f "$file.try" ]; then cat "$file.try" >> "$file"; rm -f "$file.try"; fi
done
echo "fetched $fetched bytes for a range of $((last - first + 1))"
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"
openssl rand -out store/media/big.bin 4000000
surl --directory store --cert server.pem --key server.key --user AKIAIOSFODNN7EXAMPLE:s3cret --fault "drop;after-bytes=1500000;close=graceful" s3://127.0.0.1:8080/ &
sleep 1
sh get-range.sh https://media.s3.us-east-1.amazonaws.com/big.bin 0 1999999 dl/part0 --max-time 30 --cacert server.pem --connect-to ::127.0.0.1:8080 --aws-sigv4 aws:amz:us-east-1:s3 -u AKIAIOSFODNN7EXAMPLE:s3cret
kill $(jobs -p)
